                        source: "ai",
                        spoken: "To put those numbers in context, we launched at Islands Brygge in May with only three boats and no marketing budget. By June, the weekend calendar was booked out nine days in advance, and we ended the season with over two hundred and fifty thousand euros in revenue and forty-one per cent of our customers coming back or referring friends.",
