                        source: "ai",
                        spoken: "The paradox of modern waterfront cities is that they spent billions cleaning up their canals, but made it nearly impossible for residents to actually use them. Buying a boat is a massive capital expense that sits idle most of the year, while existing rental options are either complicated, loud, or require a skipper's license.",
